-- Mock ürün görselleri: Wikimedia Commons (açık lisanslı) — picsum.photos bu ağdan erişilemediği için.
-- seed_mock.sql sonrası çalıştır.
begin;

update public.products p set
  images = v.imgs,
  image_variants = (select jsonb_agg(jsonb_build_object('url', u.url, 'color', p.colors[1 + ((u.n - 1) % array_length(p.colors, 1))]) order by u.n)
                      from unnest(v.imgs) with ordinality as u(url, n))
from (values
  ('kizil-ejderha-figuru', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg/960px-CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Dragon_print.jpg/960px-Dragon_print.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/CSIRO_ScienceImage_1861_3D_Printed_Toothless_Dragon.jpg/960px-CSIRO_ScienceImage_1861_3D_Printed_Toothless_Dragon.jpg']::text[]),
  ('eklemli-kristal-ejderha', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/CSIRO_ScienceImage_1861_3D_Printed_Toothless_Dragon.jpg/960px-CSIRO_ScienceImage_1861_3D_Printed_Toothless_Dragon.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg/960px-CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Dragon_print.jpg/960px-Dragon_print.jpg']::text[]),
  ('samuray-katana-replika-100-cm', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Katana%2C_sword_%28AM_1934.316-14%29_%28II%29.jpg/960px-Katana%2C_sword_%28AM_1934.316-14%29_%28II%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/The_Cas_Hanwei_Tactical_Katana.jpg/960px-The_Cas_Hanwei_Tactical_Katana.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Sword%2C_samurai%2C_katana_%28AM_697123%29.jpg/960px-Sword%2C_samurai%2C_katana_%28AM_697123%29.jpg']::text[]),
  ('ork-savasci-figuru', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Warhammer_AoS_Lind.jpg/960px-Warhammer_AoS_Lind.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Warhammer_Fantasy_RedCraig.jpg/960px-Warhammer_Fantasy_RedCraig.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Warhammer_painting.jpg/960px-Warhammer_painting.jpg']::text[]),
  ('anime-karakter-bustu', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/3D_selfie_in_1-20_scale_as_received_from_Shapeways%2C_the_printer_company_for_Madurodam%27s_Fantasitron_IMG_4557_FRD.jpg/960px-3D_selfie_in_1-20_scale_as_received_from_Shapeways%2C_the_printer_company_for_Madurodam%27s_Fantasitron_IMG_4557_FRD.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Doob_NY_SOHO_3D_selfie_photo_booth_IMG_4939_FRD.jpg/960px-Doob_NY_SOHO_3D_selfie_photo_booth_IMG_4939_FRD.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Doob_NY_SOHO_3D_selfie_photo_booth_IMG_4942_FRD.jpg/960px-Doob_NY_SOHO_3D_selfie_photo_booth_IMG_4942_FRD.jpg']::text[]),
  ('grifon-heykeli', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Gryf_%28Michal_Ol%C5%A1iak%29_07.jpg/960px-Gryf_%28Michal_Ol%C5%A1iak%29_07.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Statue_of_griffin_on_post_office_in_Perugia_-_Right.jpg/960px-Statue_of_griffin_on_post_office_in_Perugia_-_Right.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Statue_of_a_Griffin%2C_Parliament_building_%28Vienna%29.jpg/960px-Statue_of_a_Griffin%2C_Parliament_building_%28Vienna%29.jpg']::text[]),
  ('low-poly-ayi-saksi', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Succulent_pot_collection.jpg/960px-Succulent_pot_collection.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Succulent_Neighbors.jpg/960px-Succulent_Neighbors.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Succulent_plant_in_the_Groot-shaped_pot.jpg/960px-Succulent_plant_in_the_Groot-shaped_pot.jpg']::text[]),
