  ('ay-lambasi-ledli', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Moon_Lamp_-_New_Orleans.jpg/960px-Moon_Lamp_-_New_Orleans.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/3D_Printing_Filament_789.jpg/960px-3D_Printing_Filament_789.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/3D_Printing_Materials_%2816863368275%29.jpg/960px-3D_Printing_Materials_%2816863368275%29.jpg']::text[]),
  ('isme-ozel-anahtarlik', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Keychain_with_text_%22Encryption_is_key%22.jpg/960px-Keychain_with_text_%22Encryption_is_key%22.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Alfa_Romeo_keychain_which_came_with_an_Alfa_Romeo_33_in_the_1980s%2C_without_keys.jpg/960px-Alfa_Romeo_keychain_which_came_with_an_Alfa_Romeo_33_in_the_1980s%2C_without_keys.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Sandal_keychain.jpg/960px-Sandal_keychain.jpg']::text[]),
  ('ps5-dikey-stand', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/PlayStation_5_and_DualSense.jpg/960px-PlayStation_5_and_DualSense.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/All_PlayStations_%281-5%2C_PSP%2C_%26_Vita%29.jpg/960px-All_PlayStations_%281-5%2C_PSP%2C_%26_Vita%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/3D_Printing_Filament_789.jpg/960px-3D_Printing_Filament_789.jpg']::text[]),
