  ('cift-joystick-tutucu', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Trust_GM-1500_gamepad_controller_1.jpg/960px-Trust_GM-1500_gamepad_controller_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Xbox-360-Wireless-Controller-White.jpg/960px-Xbox-360-Wireless-Controller-White.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Trust_GM-1500_gamepad_controller_3.jpg/960px-Trust_GM-1500_gamepad_controller_3.jpg']::text[]),
  ('kablo-duzenleyici-klips-seti', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Cable_Management_Dell_1950.jpg/960px-Cable_Management_Dell_1950.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/19-inch_rackmount_Ethernet_switches_and_patch_panels.jpg/960px-19-inch_rackmount_Ethernet_switches_and_patch_panels.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Server_cable_management_%282%29_-_IMG_3548.jpg/960px-Server_cable_management_%282%29_-_IMG_3548.jpg']::text[]),
  ('baharat-rafi-organizer', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Spice_rack_with_letter_labels.jpg/960px-Spice_rack_with_letter_labels.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/3D_Printing_Filament_789.jpg/960px-3D_Printing_Filament_789.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/3D_Printing_Materials_%2816863368275%29.jpg/960px-3D_Printing_Materials_%2816863368275%29.jpg']::text[]),
  ('dis-fircasi-tutucu', array['https://upload.wikimedia.org/wikipedia/commons/6/63/Toothbrush_holder_2.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Toothbrush_holder_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/3D_Printing_Filament_789.jpg/960px-3D_Printing_Filament_789.jpg']::text[]),
  ('duvar-anahtar-organizeri', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Sandal_keychain.jpg/960px-Sandal_keychain.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/3D_Printing_Filament_789.jpg/960px-3D_Printing_Filament_789.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/3D_Printing_Materials_%2816863368275%29.jpg/960px-3D_Printing_Materials_%2816863368275%29.jpg']::text[])
) as v(slug, imgs)
where p.slug = v.slug and p.sku like 'MOCK-%';

-- Sipariş kalemlerindeki küçük görselleri ürünün ilk görseliyle eşitle
update public.orders o set items = (
  select jsonb_agg(case when p.id is not null then it || jsonb_build_object('image', p.images[1]) else it end order by ord)
    from jsonb_array_elements(o.items) with ordinality as e(it, ord)
    left join public.products p on p.id = (it ->> 'product')::uuid
)
where o.order_no like 'OZ%M%';

update public.settings set hero_slides = jsonb_build_array(
  jsonb_build_object('_id', gen_random_uuid(), 'imageUrl', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Imprimante_3D.jpg/960px-Imprimante_3D.jpg', 'altText', '3D baskı atölyesi', 'isActive', true, 'sortOrder', 0),
  jsonb_build_object('_id', gen_random_uuid(), 'imageUrl', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Backpack_3D_Printer_on_Man.jpg/960px-Backpack_3D_Printer_on_Man.jpg', 'altText', 'Sırt çantasında 3D yazıcı', 'isActive', true, 'sortOrder', 1),
  jsonb_build_object('_id', gen_random_uuid(), 'imageUrl', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/3D_printer_farm_at_Hackerspace_Wroc%C5%82aw.jpg/960px-3D_printer_farm_at_Hackerspace_Wroc%C5%82aw.jpg', 'altText', '3D yazıcı çiftliği', 'isActive', true, 'sortOrder', 2)
)
where hero_slides::text like '%picsum.photos%' or hero_slides = '[]'::jsonb;

commit;
